// The pinned reference's Expo GraphQL operations (apps/server/src/device/ExpoApi.graphql.ts,
// generated by @effect/graphql-generator), whose documents Rust's Expo API client sends as they
// are: each operation's name, kind and query text.
//
//   node scripts/reference_expo_documents.mjs <reference checkout>  > expo_documents.json
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";

const root = resolve(process.argv[2]);
const api = await import(
  pathToFileURL(resolve(root, "apps/server/src/device/ExpoApi.graphql.ts")).href
);
const names = [
  "T3ExpoViewer",
  "T3CreateEasSimulatorSession",
  "T3EasSimulatorSession",
  "T3ActiveEasSimulatorSessions",
  "T3StopEasSimulatorSession",
];
const documents = Object.fromEntries(
  names.map((name) => {
    const operation = api[name];
    if (typeof operation?.document !== "string") {
      throw new Error(`${name} no longer has a document string`);
    }
    return [name, { kind: operation.kind, query: operation.document }];
  }),
);
process.stdout.write(`${JSON.stringify(documents, null, 1)}\n`);
